tool.command:
Rscript -e '
    library(ampvis2)
    ampdata <- readRDS('${input_rds}')
    # check if there are any sequences
    if ("seqs" %in% names(ampdata)) {
        # write out the fasta file
        amp_export_fasta(
            ampdata,
            outfile = "${output_fasta}",
            taxon = ${taxon},
            seqtype = "${seqtype}"
        )
    } else {
        stop("No sequences found in the input dataset.")
    }
'
